/**
 * src/pages/ForgotPasswordPage.js: Şifremi unuttum sayfası bileşeni.
 * Kullanıcı e-posta adresini girerek şifre sıfırlama bağlantısı talep edebilir.
 *
 * @returns {JSX.Element} Şifre sıfırlama formunu içeren sayfa.
 */
import React, { useState } from 'react';
import {
  TextField,
  Button,
  Typography,
  CircularProgress,
  Alert,
  Box,
  Paper,
  Avatar,
} from '@mui/material';
import ReCAPTCHA from 'react-google-recaptcha';
import { useNavigate } from 'react-router-dom';
import LockResetIcon from '@mui/icons-material/LockReset';
import { sendResetCode } from '../services/authService';

function ForgotPasswordPage() {
  const [email, setEmail] = useState('');
  const [emailError, setEmailError] = useState('');
  const [captchaValue, setCaptchaValue] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState(false);
  const navigate = useNavigate();

  const validateEmail = (value) => {
    // Basit bir e-posta doğrulama regex'i
    const re = /\S+@\S+\.\S+/;
    return re.test(value);
  };

  const handleEmailSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    setEmailError('');

    if (!email) {
      setEmailError('E-posta adresi gereklidir.');
      setLoading(false);
      return;
    }

    if (!validateEmail(email)) {
      setEmailError('Geçerli bir e-posta adresi giriniz.');
      setLoading(false);
      return;
    }

    if (!captchaValue) {
      setError('Lütfen CAPTCHA doğrulamasını tamamlayın.');
      setLoading(false);
      return;
    }

    try {
      await sendResetCode(email, captchaValue); // Token'ı gönderiyoruz
      setSuccess(true);
    } catch (err) {
      setError(err.response?.data?.message || 'İşlem sırasında bir hata oluştu.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Box display="flex" alignItems="center" justifyContent="center" minHeight="100vh" bgcolor="#f5f5f5">
      <Paper elevation={6} sx={{ p: 4, maxWidth: 500, width: '100%' }}>
        <Box display="flex" flexDirection="column" alignItems="center" mb={2}>
          <Avatar sx={{ m: 1, bgcolor: 'secondary.main' }}><LockResetIcon /></Avatar>
          <Typography variant="h5" sx={{ fontWeight: 'bold' }}>
            Şifremi Unuttum
          </Typography>
        </Box>
        {!success ? (
          <>
            {error && <Alert severity="error">{error}</Alert>}
            <form onSubmit={handleEmailSubmit}>
              <TextField
                label="E-posta"
                variant="outlined"
                fullWidth
                margin="normal"
                required
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                error={Boolean(emailError)}
                helperText={emailError}
              />
              <ReCAPTCHA
                sitekey="6LdWer0qAAAAAPXXTthNAWq6zx0Nqhd__XwGO3q0" // Kendi site anahtarınızla değiştirin
                onChange={(value) => setCaptchaValue(value)}
              />
              <Button
                type="submit"
                variant="contained"
                color="primary"
                disabled={loading}
                startIcon={loading && <CircularProgress size={20} />}
                fullWidth
                style={{ marginTop: '16px' }}
              >
                {loading ? 'Gönderiliyor...' : 'Doğrulama Linki Gönder'}
              </Button>
            </form>
          </>
        ) : (
          <Typography variant="h6" sx={{ mt: 2, textAlign: 'center' }}>
            Şifre sıfırlama e-postası gönderildi. Lütfen e-postanızı kontrol edin ve gelen linke tıklayarak şifrenizi sıfırlayın.
          </Typography>
        )}
        <Box display="flex" justifyContent="center" mt={2}>
          <Button onClick={() => navigate('/')} color="primary">
            Anasayfaya Dön
          </Button>
        </Box>
      </Paper>
    </Box>
  );
}

export default ForgotPasswordPage;